// ============================================================
// EXTRACTING THE DETAILS
// ============================================================
// IMPORTANT:
// - Request Details is responsible for interpreting the user's
//   month input.
// - This node only uses the normalized targetMonth.
// - If no month was supplied, Request Details should already
//   have set targetMonth to the previous completed month.
// ============================================================


// ------------------------------------------------------------
// 1. GET INPUT HTML
// ------------------------------------------------------------

const html = $input.first().json.data;

if (!html || typeof html !== 'string') {
  return [
    {
      json: {
        success: false,
        message: 'No HTML data found from Get MuleSoft Monthly Release Index.'
      }
    }
  ];
}


// ------------------------------------------------------------
// 2. GET NORMALIZED MONTH FROM REQUEST DETAILS
// ------------------------------------------------------------

const request = $('Request Details').first().json;

const targetMonth = String(request.targetMonth || '').trim();

if (!targetMonth) {
  return [
    {
      json: {
        success: false,
        message: 'targetMonth is missing from Request Details.',
        requestData: request
      }
    }
  ];
}

console.log('Requested month:', request.requestedMonth);
console.log('Target month:', targetMonth);


// ------------------------------------------------------------
// 3. ESCAPE MONTH FOR REGEX
// ------------------------------------------------------------

function escapeRegex(value) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

const escapedTargetMonth = escapeRegex(targetMonth);


// ------------------------------------------------------------
// 4. FIND TARGET MONTH IN THE INDEX HTML
// ------------------------------------------------------------
// Allows normal spaces, newlines and HTML between month/year.
// Example:
// July 2026
// July
// 2026
// July <span>2026</span>
// ------------------------------------------------------------

const targetMonthRegex = new RegExp(
  escapedTargetMonth
    .replace(/\\ /g, '\\s+'),
  'i'
);

let targetMatch = targetMonthRegex.exec(html);


// ------------------------------------------------------------
// 5. FALLBACK: SEARCH IN PLAIN TEXT
// ------------------------------------------------------------

if (!targetMatch) {

  const plainText = html
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  if (
    plainText
      .toLowerCase()
      .includes(targetMonth.toLowerCase())
  ) {

    // Try a more flexible raw HTML search.
    const parts = targetMonth.split(/\s+/);

    const flexibleRegex = new RegExp(
      parts
        .map(escapeRegex)
        .join('[\\s\\n\\r]*(?:<[^>]+>[\\s\\n\\r]*)*'),
      'i'
    );

    targetMatch = flexibleRegex.exec(html);
  }
}


// ------------------------------------------------------------
// 6. IF TARGET MONTH WAS NOT FOUND
// ------------------------------------------------------------

if (!targetMatch) {

  // Get available month/year headings for debugging
  const availableMonths = [];

  const availableRegex =
    /\b(January|February|March|April|May|June|July|August|September|October|November|December)\s+20\d{2}\b/gi;

  let availableMatch;

  while ((availableMatch = availableRegex.exec(html)) !== null) {

    const value = availableMatch[0];

    if (
      !availableMonths.some(
        m => m.toLowerCase() === value.toLowerCase()
      )
    ) {
      availableMonths.push(value);
    }
  }

  return [
    {
      json: {
        success: false,
        requestedMonth: request.requestedMonth || null,
        targetMonth,
        message: `Target month "${targetMonth}" was not found in the MuleSoft monthly release index.`,
        availableMonths
      }
    }
  ];
}


// ------------------------------------------------------------
// 7. TARGET MONTH START POSITION
// ------------------------------------------------------------

const startPosition = targetMatch.index;


// ------------------------------------------------------------
// 8. FIND THE NEXT MONTH
// ------------------------------------------------------------
// We do NOT assume a specific HTML heading structure.
// This is important because MuleSoft's HTML structure can vary.
//
// Example:
// Target = May 2026
//
// We take:
//
// May 2026
//       ↓
// all May releases
//       ↓
// June 2026
//
// and stop BEFORE June 2026.
// ------------------------------------------------------------

const monthNames =
  'January|February|March|April|May|June|July|August|September|October|November|December';

const nextMonthRegex = new RegExp(
  `\\b(${monthNames})\\s+20\\d{2}\\b`,
  'gi'
);

let nextMonthPosition = html.length;

let nextMatch;

while ((nextMatch = nextMonthRegex.exec(html)) !== null) {

  if (nextMatch.index > startPosition) {

    const foundMonth = nextMatch[0];

    // Make sure this is actually a different month
    if (
      foundMonth.toLowerCase() !==
      targetMonth.toLowerCase()
    ) {
      nextMonthPosition = nextMatch.index;
      break;
    }
  }
}


// ------------------------------------------------------------
// 9. EXTRACT ONLY THE TARGET MONTH SECTION
// ------------------------------------------------------------

const monthSection = html.substring(
  startPosition,
  nextMonthPosition
);

console.log(
  `Extracted ${targetMonth} section length:`,
  monthSection.length
);


// ------------------------------------------------------------
// 10. FIND RELEASE DATES
// ------------------------------------------------------------
// Example:
//
// July 1
// July 2
// July 3
//
// Everything between two dates belongs to that date.
// ------------------------------------------------------------

const dateRegex =
  /\b(January|February|March|April|May|June|July|August|September|October|November|December)\s+(\d{1,2})(?:,\s*20\d{2})?\b/gi;

const dates = [];

let dateMatch;

while ((dateMatch = dateRegex.exec(monthSection)) !== null) {

  const dateText =
    `${dateMatch[1]} ${dateMatch[2]}`;

  // Avoid duplicate date markers
  if (
    !dates.some(
      d =>
        d.date.toLowerCase() ===
        dateText.toLowerCase()
    )
  ) {

    dates.push({
      date: dateText,
      position: dateMatch.index,
      end: dateRegex.lastIndex
    });
  }
}


console.log(
  `Dates found for ${targetMonth}:`,
  dates.map(d => d.date)
);


// ------------------------------------------------------------
// 11. EXTRACT RELEASES FOR EACH DATE
// ------------------------------------------------------------

const results = [];


// Link regex
const linkRegex =
  /<a\b[^>]*href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi;


for (let i = 0; i < dates.length; i++) {

  const currentDate = dates[i];

  const sectionStart = currentDate.end;

  const sectionEnd =
    i + 1 < dates.length
      ? dates[i + 1].position
      : monthSection.length;

  const dateSection =
    monthSection.substring(
      sectionStart,
      sectionEnd
    );


  // Reset regex state
  linkRegex.lastIndex = 0;

  let linkMatch;


  while (
    (linkMatch = linkRegex.exec(dateSection)) !== null
  ) {

    let url = linkMatch[1];

    let release = linkMatch[2];


    // --------------------------------------------------------
    // CLEAN RELEASE NAME
    // --------------------------------------------------------

    release = release
      .replace(/<script[\s\S]*?<\/script>/gi, ' ')
      .replace(/<style[\s\S]*?<\/style>/gi, ' ')
      .replace(/<[^>]+>/g, ' ')
      .replace(/&nbsp;/gi, ' ')
      .replace(/&amp;/gi, '&')
      .replace(/&quot;/gi, '"')
      .replace(/&#39;/gi, "'")
      .replace(/&#x27;/gi, "'")
      .replace(/\s+/g, ' ')
      .trim();


    if (!release) {
      continue;
    }


    // --------------------------------------------------------
    // IGNORE NAVIGATION LINKS
    // --------------------------------------------------------

    if (
      /^(RSS Feed|Copy|Edit|Menu|Home|Previous|Next)$/i
        .test(release)
    ) {
      continue;
    }


    // --------------------------------------------------------
    // CONVERT RELATIVE URL TO ABSOLUTE URL
    // --------------------------------------------------------

    let fullUrl = url;

    if (url.startsWith('../')) {

      fullUrl =
        `https://docs.mulesoft.com/release-notes/${url.substring(3)}`;

    } else if (url.startsWith('/')) {

      fullUrl =
        `https://docs.mulesoft.com${url}`;

    } else if (!/^https?:\/\//i.test(url)) {

      fullUrl =
        `https://docs.mulesoft.com/${url.replace(/^\.?\//, '')}`;
    }


    // --------------------------------------------------------
    // EXCHANGE URL FIX
    // --------------------------------------------------------

    if (
      fullUrl.includes(
        '/exchange/anypoint-exchange-release-notes'
      )
    ) {

      fullUrl =
        fullUrl.replace(
          '/exchange/anypoint-exchange-release-notes',
          '/exchange/exchange-release-notes'
        );
    }


    // --------------------------------------------------------
    // ADD RESULT
    // --------------------------------------------------------

    results.push({
      month: targetMonth,
      date: currentDate.date,
      release,
      url: fullUrl
    });
  }
}


// ------------------------------------------------------------
// 12. REMOVE DUPLICATE RELEASES
// ------------------------------------------------------------

const uniqueResults = [];

const seen = new Set();

for (const item of results) {

  const key =
    `${item.date}|${item.release}|${item.url}`
      .toLowerCase();

  if (!seen.has(key)) {

    seen.add(key);
    uniqueResults.push(item);
  }
}


// ------------------------------------------------------------
// 13. DEBUG IF NOTHING FOUND
// ------------------------------------------------------------

if (uniqueResults.length === 0) {

  return [
    {
      json: {
        success: false,
        targetMonth,
        requestedMonth: request.requestedMonth || null,
        message:
          `Month "${targetMonth}" was found, but no release links were extracted.`,
        htmlLength: html.length,
        monthSectionLength: monthSection.length,
        datesFound: dates.length,
        dates: dates.map(d => d.date)
      }
    }
  ];
}


// ------------------------------------------------------------
// 14. RETURN ONE ITEM PER RELEASE
// ------------------------------------------------------------

return uniqueResults.map(item => ({
  json: item
}));

// ============================================================
// TGH REPORT FORMAT
// Keeps existing release details and restores Description
// and aligned Compatibility / Fixed Issues columns.
// Output: text report attached as binary property "data"
// ============================================================

const firstInput = $input.first()?.json ?? {};
let releases = [];

if (Array.isArray(firstInput.releases)) {
  releases = firstInput.releases;
} else {
  releases = $input.all().map(item => item.json);
}

// -------------------- HELPERS --------------------

function clean(value, fallback = 'N/A') {
  if (value === undefined || value === null || value === '') {
    return fallback;
  }

  if (Array.isArray(value)) {
    const parts = value.map(v => clean(v, '')).filter(Boolean);
    return parts.length ? parts.join('\n') : fallback;
  }

  if (typeof value === 'object') {
    return JSON.stringify(value);
  }

  return String(value).trim() || fallback;
}

function normalizeArray(value) {
  if (value === undefined || value === null || value === '') {
    return [];
  }

  return Array.isArray(value) ? value : [value];
}

function wrapText(text, width) {
  const words = String(text ?? '').split(/\s+/);
  const lines = [];
  let line = '';

  for (const word of words) {
    if (!word) continue;

    if (!line) {
      line = word;
    } else if ((line + ' ' + word).length <= width) {
      line += ' ' + word;
    } else {
      lines.push(line);
      line = word;
    }
  }

  if (line) lines.push(line);

  return lines.length ? lines : [''];
}

function padRight(value, width) {
  const text = String(value ?? '');

  return text.length > width
    ? text.slice(0, width - 3) + '...'
    : text.padEnd(width, ' ');
}

function createTableRow(columns, widths) {
  return columns
    .map((column, index) => padRight(column, widths[index]))
    .join(' | ');
}

function createTableSeparator(widths) {
  return widths.map(width => '-'.repeat(width)).join('-+-');
}

// -------------------- DATE HELPERS --------------------

function parseReleaseDate(value, reportMonth = '') {
  if (!value) return null;

  const raw = String(value).trim();
  const isoMatch = raw.match(/^(\d{4})-(\d{2})-(\d{2})/);

  if (isoMatch) {
    const date = new Date(
      Number(isoMatch[1]),
      Number(isoMatch[2]) - 1,
      Number(isoMatch[3])
    );

    if (!Number.isNaN(date.getTime())) return date;
  }

  const textMatch = raw.match(
    /^([A-Za-z]+)\s+(\d{1,2})(?:,?\s+(\d{4}))?$/
  );

  if (textMatch) {
    let year = textMatch[3]
      ? Number(textMatch[3])
      : new Date().getFullYear();

    if (!textMatch[3] && reportMonth) {
      const yearMatch = String(reportMonth).match(/\b(20\d{2})\b/);

      if (yearMatch) year = Number(yearMatch[1]);
    }

    const date = new Date(
      `${textMatch[1]} ${Number(textMatch[2])}, ${year}`
    );

    if (!Number.isNaN(date.getTime())) return date;
  }

  const parsed = new Date(raw);

  return Number.isNaN(parsed.getTime()) ? null : parsed;
}

function formatDate(value, reportMonth = '') {
  const date = parseReleaseDate(value, reportMonth);

  if (!date) return clean(value, 'Unknown Date');

  return date.toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'long',
    day: 'numeric'
  });
}

// -------------------- COMPATIBILITY TABLE --------------------

function formatCompatibility(value) {
  const items = normalizeArray(value);

  if (!items.length) return '  N/A';

  const rows = [];

  for (const item of items) {
    if (typeof item === 'string' || typeof item === 'number') {
      rows.push({
        software: String(item),
        version: 'N/A'
      });
    } else if (item && typeof item === 'object') {
      rows.push({
        software: clean(
          item.software ??
          item.application ??
          item.applicationName ??
          item.name ??
          item.service ??
          item.component ??
          item.product,
          'N/A'
        ),
        version: clean(
          item.version ??
          item.supportedVersion ??
          item.compatibleVersion ??
          item.runtimeVersion ??
          item.value,
          'N/A'
        )
      });
    }
  }

  if (!rows.length) return '  N/A';

  const widths = [32, 24];

  const output = [
    createTableRow(['Software', 'Version'], widths),
    createTableSeparator(widths)
  ];

  for (const row of rows) {
    output.push(
      createTableRow(
        [row.software, row.version],
        widths
      )
    );
  }

  return output.map(line => '  ' + line).join('\n');
}

// -------------------- FIXED ISSUES TABLE --------------------

function formatFixedIssues(value) {
  const items = normalizeArray(value);

  if (!items.length) return '  N/A';

  const rows = [];

  for (const item of items) {
    if (typeof item === 'string' || typeof item === 'number') {
      rows.push({
        description: String(item),
        id: 'N/A'
      });
    } else if (item && typeof item === 'object') {
      rows.push({
        description: clean(
          item.description ??
          item.resolution ??
          item.issue ??
          item.summary ??
          item.details ??
          item.title,
          'N/A'
        ),
        id: clean(
          item.id ??
          item.issueId ??
          item.key ??
          item.ticket ??
          item.reference,
          'N/A'
        )
      });
    }
  }

  if (!rows.length) return '  N/A';

  const descriptionWidth = 58;
  const idWidth = 20;
  const widths = [descriptionWidth, idWidth];

  const output = [
    createTableRow(['Issue Resolution', 'ID'], widths),
    createTableSeparator(widths)
  ];

  for (const row of rows) {
    const descriptionLines = wrapText(
      row.description,
      descriptionWidth
    );

    descriptionLines.forEach((line, index) => {
      output.push(
        createTableRow(
          [line, index === 0 ? row.id : ''],
          widths
        )
      );
    });
  }

  return output.map(line => '  ' + line).join('\n');
}

// -------------------- NORMALIZE RELEASE DATA --------------------

const normalizedReleases = releases.map(release => {
  const month = clean(
    release.month ??
    release.releaseMonth ??
    firstInput.month,
    ''
  );

  const rawDate =
    release.date ??
    release.releaseDate ??
    release.publishedDate ??
    release.updatedAt ??
    null;

  return {
    ...release,

    month,
    date: formatDate(rawDate, month),
    _sortDate: parseReleaseDate(rawDate, month),

    product: clean(
      release.product ??
      release.release ??
      release.name ??
      release.title ??
      release.productName,
      'Unknown Product'
    ),

    version: clean(
      release.version ??
      release.releaseVersion ??
      release.versionNumber,
      'N/A'
    ),

    description: clean(
      release.description ??
      release.summary ??
      release.overview,
      'N/A'
    ),

    whatsNew:
      release.whatsNew ??
      release.whatIsNew ??
      release.newFeatures ??
      release.features ??
      [],

    dependentComponents:
      release.dependentComponents ??
      release.dependencies ??
      release.components ??
      [],

    compatibility:
      release.compatibility ??
      release.compatibilities ??
      release.compatibleVersions ??
      release.compatibilityNotes ??
      release.supportedSoftware ??
      release.requirements ??
      [],

    fixedIssues:
      release.fixedIssues ??
      release.issuesFixed ??
      release.bugFixes ??
      release.fixes ??
      [],

    patchVersion: clean(
      release.patchVersion ??
      release.patch ??
      release.patchLevel,
      'N/A'
    ),

    otherNotes: clean(
      release.otherNotes ??
      release.notes ??
      release.additionalNotes,
      'N/A'
    ),

    url: clean(
      release.url ??
      release.link ??
      release.releaseUrl,
      'N/A'
    )
  };
});

// -------------------- SORT RELEASES BY DATE --------------------
// Sort releases by date: oldest first, newest last.
normalizedReleases.sort((a, b) => {
  if (a._sortDate && b._sortDate) {
    return a._sortDate - b._sortDate;
  }

  if (a._sortDate) return -1;
  if (b._sortDate) return 1;

  return 0;
});

// -------------------- REPORT HEADER --------------------

const reportTitle = clean(
  firstInput.reportTitle ?? firstInput.title,
  'TGH MuleSoft Release Notes'
);

const reportMonth = clean(
  firstInput.month ?? normalizedReleases[0]?.month,
  ''
);

const reportDate = new Date().toLocaleDateString('en-US', {
  year: 'numeric',
  month: 'long',
  day: 'numeric'
});

let report = '';

report += `${reportTitle}\n`;
report += `${'='.repeat(reportTitle.length)}\n\n`;

if (reportMonth) {
  report += `Report Month: ${reportMonth}\n`;
}

report += `Generated On: ${reportDate}\n`;
report += `Total Releases: ${normalizedReleases.length}\n\n`;

// -------------------- RELEASE DETAILS --------------------

normalizedReleases.forEach((release, index) => {
  report += `${index + 1}. ${release.product}\n`;
  report += `${'-'.repeat(60)}\n`;

  report += `Release Date: ${release.date}\n`;
  report += `Version: ${release.version}\n\n`;

  // Description
  report += `Description:\n`;
  report += `${release.description}\n\n`;

  // What's New
  report += `What's New:\n`;

  const whatsNewItems = normalizeArray(release.whatsNew);

  if (whatsNewItems.length) {
    whatsNewItems.forEach(item => {
      if (item && typeof item === 'object') {
        report += `  - ${clean(
          item.description ??
          item.title ??
          item.name ??
          item.details,
          JSON.stringify(item)
        )}\n`;
      } else {
        report += `  - ${clean(item, 'N/A')}\n`;
      }
    });
  } else {
    report += `  N/A\n`;
  }

  report += '\n';

  // Dependent Components
  report += `Dependent Components:\n`;

  const components = normalizeArray(release.dependentComponents);

  if (components.length) {
    components.forEach(component => {
      if (component && typeof component === 'object') {
        const name = clean(
          component.name ??
          component.component ??
          component.application ??
          component.product,
          'N/A'
        );

        const version = clean(component.version, '');

        report += version && version !== 'N/A'
          ? `  - ${name} (${version})\n`
          : `  - ${name}\n`;
      } else {
        report += `  - ${clean(component, 'N/A')}\n`;
      }
    });
  } else {
    report += `  N/A\n`;
  }

  report += '\n';

  // Compatibility
  report += `Compatibility:\n`;
  report += `${formatCompatibility(release.compatibility)}\n\n`;

  // Fixed Issues
  report += `Fixed Issues:\n`;
  report += `${formatFixedIssues(release.fixedIssues)}\n\n`;

  // Patch Version
  report += `Patch Version: ${release.patchVersion}\n\n`;

  // Other Notes
  report += `Other Notes:\n`;
  report += `${release.otherNotes}\n\n`;

  // Release URL
  report += `Release URL: ${release.url}\n\n`;

  report += `${'='.repeat(72)}\n\n`;
});

// -------------------- OUTPUT --------------------

const fileName = 'TGH_MuleSoft_Release_Notes.txt';

const binaryData = await this.helpers.prepareBinaryData(
  Buffer.from(report, 'utf8'),
  fileName,
  'text/plain'
);

return [{
  json: {
    report,
    releaseCount: normalizedReleases.length,
    dates: [...new Set(normalizedReleases.map(r => r.date))],
    dateCount: new Set(normalizedReleases.map(r => r.date)).size
  },
  binary: {
    data: binaryData
  }
}];

// ============================================================
// MuleSoft Monthly Release Notes Extractor
// Fixed: preserve each release's individual date and metadata
// ============================================================

const items = $input.all();
const originalItems = $('Extracting the details').all();

// ============================================================
// HELPERS
// ============================================================

function decodeHtml(text) {
  return String(text || '')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&#x27;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&#x2F;/gi, '/')
    .replace(/&#8217;/gi, "'")
    .replace(/&#8220;/gi, '"')
    .replace(/&#8221;/gi, '"')
    .replace(/&#8211;/gi, '–')
    .replace(/&#8212;/gi, '—');
}

function cleanText(text) {
  return decodeHtml(text)
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<nav[\s\S]*?<\/nav>/gi, '')
    .replace(/<header[\s\S]*?<\/header>/gi, '')
    .replace(/<footer[\s\S]*?<\/footer>/gi, '')
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\\n/g, '\n')
    .replace(/\r/g, '')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n\s+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function cleanLine(text) {
  return cleanText(text).replace(/\s+/g, ' ').trim();
}

function escapeRegex(text) {
  return String(text || '').replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function unique(array) {
  return [...new Set(array.filter(Boolean))];
}

// ============================================================
// MATCH CURRENT HTTP RESPONSE TO ORIGINAL RELEASE
// ============================================================

function normalizeUrl(url) {
  return String(url || '')
    .trim()
    .replace(/\/+$/, '')
    .toLowerCase();
}

function getOriginalRelease(item) {
  const current = item.json || {};

  // Preferred: HTTP Request preserved the original metadata.
  if (current.date && (current.release || current.url)) {
    return current;
  }

  // Otherwise, match by URL instead of array index.
  const currentUrl = normalizeUrl(
    current.url ||
    current.requestUrl ||
    current.webUrl ||
    current.link ||
    ''
  );

  if (currentUrl) {
    const match = originalItems.find(original => {
      const originalUrl = normalizeUrl(
        original.json?.url || ''
      );

      return originalUrl === currentUrl;
    });

    if (match) {
      return {
        ...match.json,
        ...current,
        month: current.month || match.json.month,
        date: current.date || match.json.date,
        release: current.release || match.json.release,
        url: current.url || match.json.url
      };
    }
  }

  // Fallback: use n8n's linked-item metadata, if available.
  try {
    const linked = $('Extracting the details').itemMatching(
      items.indexOf(item)
    );

    if (linked?.json?.date) {
      return {
        ...linked.json,
        ...current,
        month: current.month || linked.json.month,
        date: current.date || linked.json.date,
        release: current.release || linked.json.release,
        url: current.url || linked.json.url
      };
    }
  } catch (error) {
    // Continue to the explicit error below.
  }

  throw new Error(
    'Cannot identify the original release metadata for this HTTP response. ' +
    'Configure Get Individual Release to preserve the input fields, ' +
    'or match its response to the original release using the URL.'
  );
}

// ============================================================
// SECTION EXTRACTION
// ============================================================

function extractSection(text, headingNames) {
  if (!text) return '';

  const names = headingNames.map(escapeRegex).join('|');

  const regex = new RegExp(
    `(?:^|\\n)\\s*(?:${names})\\s*:?\\s*\\n([\\s\\S]*?)(?=\\n\\s*(?:What's New|What’s New|Fixed Issues|Compatibility|Compability|Dependent Components used|Known Issues|Breaking Changes|Patch release version|Reference Links|$))`,
    'i'
  );

  const match = text.match(regex);
  return match ? cleanText(match[1]) : '';
}

function extractBullets(text) {
  if (!text) return [];

  return unique(
    text.split('\n')
      .map(line => line.trim())
      .map(line => line
        .replace(/^[-•·▪●◦]\s*/, '')
        .replace(/^\d+[.)]\s*/, '')
        .trim()
      )
      .filter(Boolean)
  );
}

// ============================================================
// FIXED ISSUE EXTRACTION
// ============================================================

function extractFixedIssues(text) {
  if (!text) return [];

  const lines = text.split('\n')
    .map(line => line.trim())
    .filter(Boolean);

  const issues = [];
  let currentDescription = '';

  for (const line of lines) {
    const idMatch = line.match(/\bW-\d+\b/i);

    if (idMatch) {
      const id = idMatch[0];

      let description = line.replace(id, '').trim();

      if (currentDescription) {
        description = currentDescription +
          (description ? ' ' + description : '');
      }

      if (description) {
        issues.push({ description, id });
      }

      currentDescription = '';
    } else if (
      !/^(issue resolution|description|issues|id)$/i.test(line)
    ) {
      currentDescription = line;
    }
  }

  return issues;
}

// ============================================================
// COMPATIBILITY EXTRACTION
// ============================================================

function extractCompatibility(text) {
  if (!text) return [];

  const lines = text.split('\n')
    .map(line => line.trim())
    .filter(Boolean);

  const results = [];

  const knownSoftware = [
    'Mule runtime engine',
    'Mule Runtime Engine',
    'Mule',
    'Anypoint Studio',
    'OpenJDK',
    'Java',
    'Apache Mina SSHD',
    'DataWeave',
    'JDK',
    'Java Runtime'
  ];

  for (let i = 0; i < lines.length; i++) {
    const software = knownSoftware.find(
      name => lines[i].toLowerCase() === name.toLowerCase()
    );

    if (software && lines[i + 1]) {
      const version = lines[i + 1];

      if (/\d/.test(version) || /later|and|or/i.test(version)) {
        results.push({
          software,
          version
        });
      }
    }
  }

  return results;
}

// ============================================================
// VERSION EXTRACTION
// ============================================================

function extractVersion(text) {
  const candidates = [];
  const regex = /\b([0-9]+\.[0-9]+(?:\.[0-9]+)+)\b/g;

  let match;

  while ((match = regex.exec(text)) !== null) {
    candidates.push(match[1]);
  }

  return unique(candidates)[0] || '';
}

// ============================================================
// DESCRIPTION EXTRACTION — MULESOFT PRODUCT INTRODUCTION
// ============================================================

function extractDescription(html) {
  html = String(html || '');

  if (!html) return '';

  // Locate the preamble containing the product description.
  const preambleStart = html.search(
    /<div\b[^>]*\bid=["']preamble["'][^>]*>/i
  );

  if (preambleStart === -1) return '';

  const preambleHtml = html.slice(preambleStart);

  // Stop before the release-history sections.
  const sectionStart = preambleHtml.search(
    /<div\b[^>]*class=["'][^"']*\bsect1\b[^"']*["']/i
  );

  const preamble = sectionStart >= 0
    ? preambleHtml.slice(0, sectionStart)
    : preambleHtml.slice(0, 15000);

  // Extract paragraph text from the preamble.
  const paragraphs = [
    ...preamble.matchAll(/<p\b[^>]*>([\s\S]*?)<\/p>/gi)
  ];

  for (const match of paragraphs) {
    const description = decodeHtml(
      match[1]
        .replace(/<!--[\s\S]*?-->/g, '')
        .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, '')
        .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, '')
        .replace(/<[^>]+>/g, ' ')
    )
      .replace(/\s+/g, ' ')
      .trim();

    // Skip support category, guide links, and empty text.
    if (!description) continue;
    if (/^Support Category\s*:/i.test(description)) continue;
    if (/^Guide\s*:/i.test(description)) continue;

    // Reject generic website/navigation text.
    if (
      /mulesoft documentation site/i.test(description) ||
      /view as markdown|view llms\.txt/i.test(description) ||
      /getting started.*community.*training/i.test(description)
    ) {
      continue;
    }

    return description;
  }

  return '';
}

// ============================================================
// MONTH SECTION
// ============================================================

function extractMonthSection(html, month) {
  if (!html || !month) return '';

  const escapedMonth = escapeRegex(month);

  const headingRegex = new RegExp(
    `<h[1-6][^>]*>\\s*(?:<[^>]+>\\s*)*${escapedMonth}(?:\\s*<[^>]+>)*\\s*<\\/h[1-6]>`,
    'i'
  );

  const match = headingRegex.exec(html);

  if (!match) return cleanText(html);

  const start = match.index + match[0].length;

  const monthNames =
    'January|February|March|April|May|June|July|August|September|October|November|December';

  const nextMonthRegex = new RegExp(
    `<h[1-6][^>]*>[\\s\\S]*?(?:${monthNames})\\s+20\\d{2}[\\s\\S]*?<\\/h[1-6]>`,
    'gi'
  );

  nextMonthRegex.lastIndex = start;

  const next = nextMonthRegex.exec(html);
  const end = next ? next.index : html.length;

  return cleanText(html.substring(start, end));
}

// ============================================================
// DATE SECTION
// ============================================================

function extractDateSection(monthText, targetDate) {
  if (!monthText || !targetDate) return monthText;

  const escapedDate = escapeRegex(targetDate);

  const dateRegex = new RegExp(
    `(?:^|\\n)\\s*${escapedDate}\\s*(?:\\n|$)`,
    'i'
  );

  const match = dateRegex.exec(monthText);

  if (!match) return monthText;

  const start = match.index + match[0].length;

  const nextDateRegex =
    /\n\s*(?:January|February|March|April|May|June|July|August|September|October|November|December)\s+\d{1,2}\s*\n/gi;

  nextDateRegex.lastIndex = start;

  const next = nextDateRegex.exec(monthText);
  const end = next ? next.index : monthText.length;

  return monthText.substring(start, end).trim();
}

// ============================================================
// PROCESS RELEASES — PRESERVE INDIVIDUAL DATES
// ============================================================

return items.map(item => {
  const current = item.json || {};

  // Resolve this response to its own original release.
  const original = getOriginalRelease(item);

  const html = current.data || current.releaseHtml || '';

  const month = original.month || '';
  const date = original.date || '';
  const release = original.release || '';
  const url = original.url || '';

  if (!date) {
    throw new Error(
      `Release date missing for "${release || url || 'unknown release'}".`
    );
  }

  const fullText = cleanText(html);

  const titleMatch = html.match(
    /<title[^>]*>([\s\S]*?)<\/title>/i
  );

  const pageTitle = titleMatch
    ? cleanLine(titleMatch[1])
    : '';

  const monthSection = extractMonthSection(html, month);

  const dateSection = extractDateSection(monthSection, date);

  const releaseText =
    dateSection && dateSection.length > 100
      ? dateSection
      : monthSection || fullText;

  const description = extractDescription(html);

  const whatsNew = extractBullets(
    extractSection(releaseText, [
      "What's New",
      'What’s New',
      "What's new",
      'What’s new'
    ])
  );

  const dependentComponents = extractBullets(
    extractSection(releaseText, [
      'Dependent Components used',
      'Dependent Components Used',
      'Dependent Components'
    ])
  );

  const fixedIssues = extractFixedIssues(
    extractSection(releaseText, [
      'Fixed Issues',
      'Fixed Issues:'
    ])
  );

  const compatibility = extractCompatibility(
    extractSection(releaseText, [
      'Compatibility',
      'Compability'
    ])
  );

  const patchMatch = releaseText.match(
    /Patch\s+release\s+version\s*:\s*([0-9]+(?:\.[0-9]+)+)/i
  );

  const patchVersion = patchMatch ? patchMatch[1] : '';
  const version = extractVersion(releaseText);

  let otherNotes = '';

  const otherPatterns = [
    /This patch update addresses the following[\s\S]*?(?=\n\s*(?:Description|Issue Resolution|ID))/i,
    /DataWeave[\s\S]*?(?=\n\s*(?:Reference Links|$))/i
  ];

  for (const pattern of otherPatterns) {
    const match = releaseText.match(pattern);

    if (match) {
      otherNotes = cleanText(match[0]);
      break;
    }
  }

  const result = {
    month,
    date,
    product: release,
    description,
    version,
    patchVersion,
    whatsNew,
    dependentComponents,
    fixedIssues,
    compatibility,
    otherNotes,
    url,
    pageTitle
  };

  // Remove empty fields while retaining the release date.
  for (const key of Object.keys(result)) {
    if (
      key !== 'date' &&
      (
        result[key] === '' ||
        result[key] === null ||
        result[key] === undefined ||
        (Array.isArray(result[key]) && result[key].length === 0)
      )
    ) {
      delete result[key];
    }
  }

  return { json: result };
});

// ============================================================
// PREPARE REQUEST
// Accept flexible month formats
// ============================================================

const input = $input.first().json;
const body = input.body || input;


// ============================================================
// EMAIL
// ============================================================

const email = String(body.email || '').trim();

if (!email) {
  throw new Error('Email address is required.');
}

const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

if (!emailRegex.test(email)) {
  throw new Error(`Invalid email address: ${email}`);
}


// ============================================================
// CURRENT DATE
// ============================================================

const now = new Date();

const currentYear = now.getFullYear();
const currentMonthIndex = now.getMonth();

const monthNames = [
  'January',
  'February',
  'March',
  'April',
  'May',
  'June',
  'July',
  'August',
  'September',
  'October',
  'November',
  'December'
];


// ============================================================
// GET MONTH INPUT
// ============================================================

const rawMonth = String(body.month || '').trim();

let targetYear;
let targetMonthIndex;


// ============================================================
// NO MONTH PROVIDED
//
// Automatically use previous completed month.
//
// Example:
// Current = August 2026
// Target  = July 2026
// ============================================================

if (!rawMonth) {

  const previousMonth = new Date(
    currentYear,
    currentMonthIndex - 1,
    1
  );

  targetYear = previousMonth.getFullYear();
  targetMonthIndex = previousMonth.getMonth();

}


// ============================================================
// MONTH PROVIDED
// ============================================================

else {

  const value = rawMonth
    .toLowerCase()
    .trim()
    .replace(/\./g, '');

  let parsed = false;


  // ==========================================================
  // MONTH NAME LOOKUP
  // ==========================================================

  const fullMonths = {
    january: 0,
    february: 1,
    march: 2,
    april: 3,
    may: 4,
    june: 5,
    july: 6,
    august: 7,
    september: 8,
    october: 9,
    november: 10,
    december: 11
  };

  const shortMonths = {
    jan: 0,
    feb: 1,
    mar: 2,
    apr: 3,
    may: 4,
    jun: 5,
    jul: 6,
    aug: 7,
    sep: 8,
    sept: 8,
    oct: 9,
    nov: 10,
    dec: 11
  };


  // ==========================================================
  // FORMAT:
  // July 2026
  // Jul 2026
  // July
  // Jul
  // ==========================================================

  const nameMatch = value.match(
    /^([a-z]+)(?:\s+(\d{4}))?$/
  );

  if (nameMatch) {

    const monthName = nameMatch[1];
    const suppliedYear = nameMatch[2];

    if (
      Object.prototype.hasOwnProperty.call(
        fullMonths,
        monthName
      )
    ) {

      targetMonthIndex =
        fullMonths[monthName];

      targetYear =
        suppliedYear
          ? Number(suppliedYear)
          : currentYear;

      parsed = true;

    } else if (
      Object.prototype.hasOwnProperty.call(
        shortMonths,
        monthName
      )
    ) {

      targetMonthIndex =
        shortMonths[monthName];

      targetYear =
        suppliedYear
          ? Number(suppliedYear)
          : currentYear;

      parsed = true;
    }
  }


  // ==========================================================
  // FORMAT:
  // 2026-07
  // ==========================================================

  if (!parsed) {

    const match = value.match(
      /^(\d{4})-(\d{1,2})$/
    );

    if (match) {

      targetYear = Number(match[1]);
      targetMonthIndex = Number(match[2]) - 1;

      parsed = true;
    }
  }


  // ==========================================================
  // FORMAT:
  // 07-2026
  // ==========================================================

  if (!parsed) {

    const match = value.match(
      /^(\d{1,2})-(\d{4})$/
    );

    if (match) {

      targetMonthIndex = Number(match[1]) - 1;
      targetYear = Number(match[2]);

      parsed = true;
    }
  }


  // ==========================================================
  // FORMAT:
  // 07/26
  //
  // Interpret as:
  // month/year
  //
  // 07/26 → July 2026
  // ==========================================================

  if (!parsed) {

    const match = value.match(
      /^(\d{1,2})\/(\d{2})$/
    );

    if (match) {

      targetMonthIndex =
        Number(match[1]) - 1;

      targetYear =
        2000 + Number(match[2]);

      parsed = true;
    }
  }


  // ==========================================================
  // ALSO ACCEPT:
  // 07/2026
  // ==========================================================

  if (!parsed) {

    const match = value.match(
      /^(\d{1,2})\/(\d{4})$/
    );

    if (match) {

      targetMonthIndex =
        Number(match[1]) - 1;

      targetYear =
        Number(match[2]);

      parsed = true;
    }
  }


  // ==========================================================
  // INVALID INPUT
  // ==========================================================

  if (!parsed) {

    throw new Error(
      `Could not understand the month "${rawMonth}".`
    );
  }
}


// ============================================================
// VALIDATE MONTH
// ============================================================

if (
  targetMonthIndex < 0 ||
  targetMonthIndex > 11 ||
  !Number.isInteger(targetYear) ||
  targetYear < 2000
) {

  throw new Error(
    `Invalid month: ${rawMonth}`
  );
}


// ============================================================
// TARGET DATE
// ============================================================

const targetDate = new Date(
  targetYear,
  targetMonthIndex,
  1
);


// ============================================================
// NEVER ALLOW CURRENT MONTH
// NEVER ALLOW FUTURE MONTHS
// ============================================================

const currentMonthStart = new Date(
  currentYear,
  currentMonthIndex,
  1
);

if (targetDate >= currentMonthStart) {

  throw new Error(
    `The requested month "${rawMonth}" is the current or a future month. ` +
    `Current month is ${monthNames[currentMonthIndex]} ${currentYear}.`
  );
}


// ============================================================
// NORMALIZED MONTH
// ============================================================

const targetMonth =
  `${monthNames[targetMonthIndex]} ${targetYear}`;


// ============================================================
// OUTPUT
// ============================================================

return [
  {
    json: {
      email,

      // Normalized internally
      targetMonth,

      targetYear,

      targetMonthIndex,

      targetMonthNumber:
        targetMonthIndex + 1,

      // Keep original user input for logging/debugging
      requestedMonth:
        rawMonth || null,

      // True when user did not provide month
      usedPreviousMonth:
        rawMonth === ''
    }
  }
];

const items = $input.all();

if (items.length === 0) {
  throw new Error('No release data received.');
}

const releases = items
  .map(item => item.json)
  .filter(item => item && item.month);

if (releases.length === 0) {
  throw new Error(
    'No valid releases found. Check the Combined Data output.'
  );
}

return [
  {
    json: {
      month: releases[0].month,
      totalReleases: releases.length,
      releases: releases
    }
  }
];

const input = $input.first().json;

if (!input.releases || !Array.isArray(input.releases)) {
  throw new Error(
    'No releases array found. Check the Aggregate Releases node output.'
  );
}

const releases = input.releases.map((release) => ({
  month: release.month ?? input.month ?? '',
  date: release.date ?? '',
  product: release.product ?? '',
  description: release.description ?? '',
  version: release.version ?? '',
  patchVersion: release.patchVersion ?? '',
  whatsNew: Array.isArray(release.whatsNew)
    ? release.whatsNew
    : [],
  dependentComponents: Array.isArray(release.dependentComponents)
    ? release.dependentComponents
    : [],
  compatibility: Array.isArray(release.compatibility)
    ? release.compatibility
    : [],
  fixedIssues: Array.isArray(release.fixedIssues)
    ? release.fixedIssues
    : [],
  otherNotes: Array.isArray(release.otherNotes)
    ? release.otherNotes
    : [],
  url: release.url ?? ''
}));

return [
  {
    json: {
      reportTitle: 'MuleSoft Release Notes',
      reportMonth: input.month ?? '',
      generatedOn: new Date().toLocaleDateString('en-GB'),
      totalReleases: releases.length,
      releases
    }
  }
];
